def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    # Iterate over possible starting points for the prefix in s
    for i in range(len(s) - len(prefix) + 1):
        if s[i:i + len(prefix)] == prefix:
            # Check if a matching suffix can exist after this prefix
            if s[i + len(prefix):].startswith(suffix):
                return True
    # Check if suffix can match starting from the beginning
    for i in range(len(s) - len(suffix) + 1):
        if s[i:i + len(suffix)] == suffix:
            # Ensure that a matching prefix can exist before this suffix
            if s[:i].endswith(prefix):
                return True
    return False

