def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    from collections import defaultdict, deque
    import sys

    # Create a graph representation
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[v].append((u, w))  # Reverse the graph for easier reachability check

    def bfs(max_weight: int) -> bool:
        # BFS to check if all nodes can reach node 0 with edges <= max_weight
        queue = deque([0])
        visited = set([0])
        while queue:
            node = queue.popleft()
            for neighbor, weight in graph[node]:
                if neighbor not in visited and weight <= max_weight:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return len(visited) == n

    # Binary search for the minimum possible maximum weight
    low, high = 1, 10**6
    result = -1
    while low <= high:
        mid = (low + high) // 2
        # Check if we can reach all nodes with the maximum edge weight of mid
        if bfs(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    # Now check if we can satisfy the outgoing edges constraint
    def can_satisfy_threshold(max_weight: int) -> bool:
        outgoing_count = defaultdict(int)
        for u, v, w in edges:
            if w <= max_weight:
                outgoing_count[u] += 1
                if outgoing_count[u] > threshold:
                    return False
        return True

    # Final check with the found result
    if result != -1 and can_satisfy_threshold(result):
        return result
    return -1

