def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize the DP table for first half of houses
    dp1 = [[float('inf')] * 3 for _ in range(n // 2)]
    # Initialize the DP table for second half of houses
    dp2 = [[float('inf')] * 3 for _ in range(n // 2)]

    # Fill the base cases for first half
    for j in range(3):
        dp1[0][j] = cost[0][j]

    # Fill the DP table for the first half
    for i in range(1, n // 2):
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp1[i][j] = min(dp1[i][j], cost[i][j] + dp1[i - 1][k])

    # Fill the base cases for second half
    for j in range(3):
        dp2[0][j] = cost[n // 2][j]

    # Fill the DP table for the second half
    for i in range(1, n // 2):
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp2[i][j] = min(dp2[i][j], cost[n // 2 + i][j] + dp2[i - 1][k])

    # Calculate the minimal cost considering the equidistant constraint
    min_cost = float('inf')
    for j in range(3):
        for k in range(3):
            if j != k:  # colors of first and last house must differ
                min_cost = min(min_cost, dp1[n // 2 - 1][j] + dp2[n // 2 - 1][k])

    return min_cost

