def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers  # Initialize mention counts
    online_status = [True] * numberOfUsers  # Initial online status for all users

    # Process events sorted by timestamp
    events_sorted = sorted((int(event[1]), event[0], event[2]) for event in events)

    for timestamp, event_type, data in events_sorted:
        # Process offline events
        if event_type == 'OFFLINE':
            user_id = int(data)
            online_status[user_id] = False  # Set user offline
            # Schedule the user to come back online after 60 units
            for i in range(len(events_sorted)):
                if events_sorted[i][0] == timestamp and events_sorted[i][1] == 'MESSAGE':
                    continue  # Skip in the same timestamp
                if events_sorted[i][0] == timestamp + 60:
                    online_status[user_id] = True
                    break
        elif event_type == 'MESSAGE':
            # Identify mentioned users
            if data == 'HERE':
                mentioned_users = [i for i in range(numberOfUsers) if online_status[i]]
            elif data == 'ALL':
                mentioned_users = range(numberOfUsers)
            else:
                mentioned_users = []
                ids = data.split()  # Split mentions
                for user_id in ids:
                    if user_id.startswith('id'):
                        mentioned_users.append(int(user_id[2:]))

            # Update mentions count
            for user_id in mentioned_users:
                mentions[user_id] += 1

    return mentions

def maxDistance(s: str, k: int) -> int:
    x, y = 0, 0
    max_distance = 0
    for char in s:
        if char == 'N':
            y += 1
        elif char == 'S':
            y -= 1
        elif char == 'E':
            x += 1
        elif char == 'W':
            x -= 1
        current_distance = abs(x) + abs(y)
        # max possible distance if we change a character
        possible_distance = current_distance + min(k, (len(s) - (x + y) - (x - y))) + (current_distance < k)
        max_distance = max(max_distance, possible_distance)
